import { cp, mkdir, readFile, readdir, rm, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { execFileSync } from 'node:child_process';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const output = path.resolve(process.argv[2] || path.join(root, '.preview/jsx'));
const marker = '.jsx-preview-output';
// Never replace a directory that wasn't previously generated by this builder.
const existing = await readdir(output).catch(error => {
  if (error.code === 'ENOENT') return [];
  throw error;
});
if (existing.length && !existing.includes(marker)) throw new Error('Preview output must be empty or contain ' + marker);
await mkdir(output, { recursive: true });
await writeFile(path.join(output, marker), 'Generated JSX preview only.\n');
for (const entry of existing.filter(entry => entry !== marker)) await rm(path.join(output, entry), { recursive: true, force: true });
const jsxOutput = path.join(output, 'tools/jsx');
await mkdir(jsxOutput, { recursive: true });
// Explicit public assets only: no backend, credentials, other tools, or Git metadata.
const assets = ['index.html', 'app.js', 'route-map.js', 'map-data.js', 'fares.js', 'styles.css',
  'searchable-select.js', 'searchable-select.css', 'favicon.svg', 'favicon-32.png',
  'apple-touch-icon.png', 'nunito-latin.woff2', 'Nunito-OFL.txt', 'plane.svg', 'images'];
for (const asset of assets) await cp(path.join(root, 'tools/jsx', asset), path.join(jsxOutput, asset), { recursive: true });
let html = await readFile(path.join(jsxOutput, 'index.html'), 'utf8');
html = html.replace(/<script\b[^>]*src="\/assets\/js\/analytics\.js[^\"]*"[^>]*><\/script>/g, '<script src="./preview.js"></script>');
if (html.includes('/assets/js/analytics.js')) throw new Error('Production analytics must not be in a preview');
html = html.replace('<title>', '<meta name="robots" content="noindex, nofollow">\n  <title>Draft · ');
html = html.replace('</head>', '<link rel="stylesheet" href="./preview.css">\n</head>');
html = html.replace('<body>', '<body>\n<aside class="preview-banner" aria-label="Preview environment"><span><strong>Draft preview</strong> · Analytics off · External JSX links are real</span><button id="preview-reset" type="button">Reset walkthrough</button></aside>');
await writeFile(path.join(jsxOutput, 'index.html'), html);
await writeFile(path.join(jsxOutput, 'preview.js'), `// Preview-only event buffer; nothing is sent to PostHog.
window.JSXPreviewEvents = [];
window.SiteAnalytics = { capture(event, properties) {
  window.JSXPreviewEvents.push({ event, properties });
  if (window.JSXPreviewEvents.length > 100) window.JSXPreviewEvents.shift();
} };
document.addEventListener('DOMContentLoaded', () => {
  document.getElementById('preview-reset').addEventListener('click', () => {
    try { localStorage.removeItem('jsx-account-prompt-seen-v1'); localStorage.removeItem('jsx-guide-hidden-v1'); } catch {}
    location.reload();
  });
});
`);
await writeFile(path.join(jsxOutput, 'preview.css'), '.preview-banner{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px;padding:8px 18px;background:#f5f4f2;border-bottom:1px solid #ddd;color:#514c48;font:12px/1.5 Nunito,Arial,sans-serif}.preview-banner button{border-radius:8px;min-height:36px;padding:5px 10px;font-size:12px}@media(max-width:600px){.preview-banner{padding:8px 16px}.preview-banner button{min-height:44px}}\n');
await writeFile(path.join(output, 'index.html'), '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="robots" content="noindex, nofollow"><title>JSX draft preview</title><script>location.replace("./tools/jsx/" + location.search + location.hash)</script></head><body><a href="./tools/jsx/">Open JSX draft preview</a></body></html>\n');
await writeFile(path.join(output, 'robots.txt'), 'User-agent: *\nDisallow: /\n');
await writeFile(path.join(output, '_headers'), '/*\n  X-Robots-Tag: noindex, nofollow\n');
const commit = execFileSync('git', ['rev-parse', 'HEAD'], { cwd: root, encoding: 'utf8' }).trim();
const dirty = Boolean(execFileSync('git', ['status', '--porcelain', '--', 'tools/jsx', 'assets/js/analytics.js', 'scripts/preview'], { cwd: root, encoding: 'utf8' }).trim());
await writeFile(path.join(output, 'preview-build.json'), JSON.stringify({ commit, dirty, builtAt: new Date().toISOString() }, null, 2) + '\n');
console.log(JSON.stringify({ output, commit, dirty }));
